INSERT INTO [dbo].[knowledge_chunks] ([id],[document_id],[content],[chunk_index]) VALUES (NEWID(), 'eb80f89c-c9f7-431e-b74a-3b541bcb1412', N'ael Ostfeld <yaelob@tripex.io>,moshe hay <moshe.hay@biu.ac.il>,<support@combtas.com
